#include <bits/stdc++.h>
using namespace std;
int main(){
    int P,R;
    int caseNum=0;
    while(cin>>P>>R && !(P==0&&R==0)){
        map<string,int> id;
        vector<vector<int>> adj;
        auto getId=[&](const string&s)->int{
            auto it=id.find(s);
            if(it!=id.end()) return it->second;
            int nid=(int)id.size();
            id[s]=nid;
            adj.push_back({});
            return nid;
        };
        for(int i=0;i<R;i++){
            string a,b; cin>>a>>b;
            int ai=getId(a), bi=getId(b);
            adj[ai].push_back(bi);
            adj[bi].push_back(ai);
        }
        int n=(int)id.size();
        int diameter=0;
        bool disconnected=(n<P);
        for(int s=0;s<n;s++){
            vector<int> dist(n,-1);
            queue<int>q; dist[s]=0;q.push(s);
            int reached=1;
            while(!q.empty()){
                int u=q.front();q.pop();
                for(int v: adj[u]) if(dist[v]==-1){dist[v]=dist[u]+1;q.push(v);reached++;diameter=max(diameter,dist[v]);}
            }
            if(reached<n) disconnected=true;
        }
        caseNum++;
        if(caseNum>1) cout << "\n";
        cout << "Network " << caseNum << ": " << (disconnected? string("DISCONNECTED") : to_string(diameter)) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,r,tc=0;
    while (cin>>n>>r && (n||r)) {
        tc++;
        vector<vector<int>> cap(n+1, vector<int>(n+1,0));
        for (int i=0;i<r;i++){
            int c1,c2,p; cin>>c1>>c2>>p;
            cap[c1][c2] = max(cap[c1][c2], p);
            cap[c2][c1] = max(cap[c2][c1], p);
        }
        int s,d; long long t; cin>>s>>d>>t;
        vector<int> best(n+1,0); vector<bool> done(n+1,false);
        best[s] = INT_MAX;
        for (int iter=0; iter<n; iter++){
            int u=-1;
            for (int i=1;i<=n;i++) if(!done[i] && (u==-1||best[i]>best[u])) u=i;
            if (u==-1 || best[u]==0) break;
            done[u]=true;
            for (int v=1; v<=n; v++) if(cap[u][v]>0) best[v]=max(best[v], min(best[u], cap[u][v]));
        }
        long long trips = s == d ? 0 : (t + best[d] - 2) / (best[d] - 1);
        if (tc>1) cout << "\n";
        cout << "Scenario #" << tc << "\n";
        cout << "Minimum Number of Trips = " << trips << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int M,N;
    while (cin >> M >> N) {
        vector<string> grid(M);
        for (auto &s: grid) cin >> s;
        int X,Y; cin >> X >> Y;
        char land=grid[X][Y];
        int dx[4]={-1,1,0,0}, dy[4]={0,0,-1,1};
        vector<vector<bool>> kingVis(M, vector<bool>(N,false));
        {
            queue<pair<int,int>> q; q.push({X,Y}); kingVis[X][Y]=true;
            while(!q.empty()){
                auto [x,y]=q.front(); q.pop();
                for(int d=0;d<4;d++){
                    int nx=x+dx[d], ny=(y+dy[d]+N)%N;
                    if(nx<0||nx>=M) continue;
                    if(kingVis[nx][ny]) continue;
                    if(grid[nx][ny]!=land) continue;
                    kingVis[nx][ny]=true; q.push({nx,ny});
                }
            }
        }
        vector<vector<bool>> seen(M, vector<bool>(N,false));
        int best=0;
        for(int i=0;i<M;i++) for(int j=0;j<N;j++){
            if (grid[i][j]!=land || seen[i][j] || kingVis[i][j]) continue;
            queue<pair<int,int>> q; q.push({i,j}); seen[i][j]=true;
            int size=0;
            while(!q.empty()){
                auto [x,y]=q.front(); q.pop(); size++;
                for(int d=0;d<4;d++){
                    int nx=x+dx[d], ny=(y+dy[d]+N)%N;
                    if(nx<0||nx>=M) continue;
                    if(seen[nx][ny]) continue;
                    if(grid[nx][ny]!=land) continue;
                    seen[nx][ny]=true; q.push({nx,ny});
                }
            }
            best=max(best,size);
        }
        cout << best << "\n";
    }
}
